
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_23_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_23", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.234765311816910e+00, -5.133991445838518e+00, -4.992578139145015e+00, -4.796200445062653e+00, -4.527405911873559e+00, -4.166491653603227e+00, -3.693110359768573e+00, -3.086458031001125e+00, -2.324433048961812e+00, -1.456428912876752e+00, -8.043809639343555e-01, -6.039424265252912e-01, -6.362919419295893e-01, -5.503716861402361e-01, -3.617262917562908e-01, -1.798547131371580e-01, -7.245632212923632e-02, -2.336260858927585e-02, -4.991528097110678e-03, -5.611231035500656e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


